 IF (SELECT COUNT(*)FROM object WHERE `id` <=> 228440 AND `zoneid` <=> 202 AND `version` <=> 0 AND BINARY CAST(`xpos` AS CHAR) <=> BINARY CONVERT(0x393332 USING utf8mb4) AND BINARY CAST(`ypos` AS CHAR) <=> BINARY CONVERT(0x2d333435 USING utf8mb4) AND BINARY CAST(`zpos` AS CHAR) <=> BINARY CONVERT(0x2d3936 USING utf8mb4) AND BINARY CAST(`heading` AS CHAR) <=> BINARY CONVERT(0x313930 USING utf8mb4) AND `itemid` <=> 0 AND `charges` <=> 0 AND BINARY `objectname` <=> BINARY CONVERT(0x495431303830325f4143544f52444546 USING utf8mb4) AND `type` <=> 16 AND `icon` <=> 892 AND BINARY CAST(`size_percentage` AS CHAR) <=> BINARY CONVERT(0x30 USING utf8mb4) AND `unknown24` <=> 0 AND `unknown60` <=> 0 AND `unknown64` <=> 0 AND `unknown68` <=> 0 AND `unknown72` <=> 0 AND `unknown76` <=> 0 AND `unknown84` <=> 0 AND BINARY CAST(`size` AS CHAR) <=> BINARY CONVERT(0x313030 USING utf8mb4) AND `solid_type` <=> 0 AND `incline` <=> 0 AND BINARY CAST(`tilt_x` AS CHAR) <=> BINARY CONVERT(0x30 USING utf8mb4) AND BINARY CAST(`tilt_y` AS CHAR) <=> BINARY CONVERT(0x30 USING utf8mb4) AND BINARY `display_name` <=> BINARY CONVERT(0x4c6f6f6d USING utf8mb4) AND `min_expansion` <=> 11 AND `max_expansion` <=> 99 AND `content_flags` <=> NULL AND `content_flags_disabled` <=> NULL)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC290 actual owned world loom preimage drift'; END IF;

